-- 1) Zdravé tělo (silový trénink): nová fotka na přání studia (26. 11. 2026) – ženy na fitness strojích u oken (spinningové kolo,
--    air bike, veslařský trenažér, SkiErg, eliptical), stejný sál, teplý tón a štítek OCTOPUSH jako u ostatních lekcí.
--    Vytvořená pomocí AI. Vymění se jen při prvním spuštění (dokud obrázek není mezi nahranými); fotku, kterou studio
--    později vybere v Admin → Lekce, opakované spuštění nepřepíše.
UPDATE "class_types" SET "image_url" = '/media/25cb3853-9af9-4802-98a3-e31daf62e750.webp'
WHERE "name" ILIKE 'Zdravé tělo%' AND "name" NOT ILIKE '%cardio%'
  AND NOT EXISTS (SELECT 1 FROM "media" WHERE "id" = '25cb3853-9af9-4802-98a3-e31daf62e750');
--> statement-breakpoint
INSERT INTO "media" ("id", "filename", "mime", "width", "height", "size", "data") VALUES
  ('25cb3853-9af9-4802-98a3-e31daf62e750', 'lekce-zdrave-telo.webp', 'image/webp', 1600, 900, 160658, decode('', 'base64'))
ON CONFLICT ("id") DO NOTHING;
--> statement-breakpoint
UPDATE "settings" SET "value" = (SELECT jsonb_agg(x ORDER BY x) FROM (SELECT DISTINCT jsonb_array_elements_text("value" || '["/media/25cb3853-9af9-4802-98a3-e31daf62e750.webp"]'::jsonb) x) s)
WHERE "key" = 'aiImages' AND jsonb_typeof("value") = 'array' AND NOT "value" ? '/media/25cb3853-9af9-4802-98a3-e31daf62e750.webp';
